 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0 for _ in range((w+2)//3)] for _ in range((h+2)//3)]
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color in (0, 5) or (r,c) in seen:
                continue
            stack=[(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                y,x=stack.pop(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    p=(y+dy,x+dx)
                    if 0<=p[0]<h and 0<=p[1]<w and p not in seen and grid[p[0]][p[1]]==color:
                        seen.add(p); stack.append(p)
            cy=sum(y for y,x in cells)//len(cells)
            cx=sum(x for y,x in cells)//len(cells)
            out[cy//3][cx//3]=color
    return out
